return $input.all().map((item) => {
  const j = item.json ?? {};

  // Mengambil HTML dari hasil PDF.co
  let html = j.data ?? j.body ?? j.html ?? '';

  // PDF.co dapat mengembalikan HTML dalam objek
  if (typeof html === 'object' && html !== null) {
    html = html.body ?? html.html ?? html.text ?? '';
  }

  html = String(html);

  // Membersihkan script dan style
  const clean = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<head[\s\S]*?<\/head>/gi, ' ')

    // Menghapus semua tag HTML
    .replace(/<[^>]*>/g, ' ')

    // Membersihkan karakter HTML
    .replace(/&nbsp;|&#160;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")

    // Menghapus metadata halaman
    .replace(/\b(Page|Halaman)\s+\d+(\s+of\s+\d+)?\b/gi, ' ')

    // Merapikan spasi dan baris
    .replace(/[\t\r]+/g, ' ')
    .replace(/ {2,}/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();

  return {
    json: {
      candidate_name: 'CV Kandidat',
      clean_text: clean
    }
  };
});

return $input.all().map((item) => {
  const raw = item.json.output
    ?? item.json.text
    ?? item.json.response
    ?? item.json.content
    ?? '';

  const str = typeof raw === 'string'
    ? raw
    : JSON.stringify(raw);

  const cleaned = str
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');

  if (start === -1 || end === -1) {
    throw new Error('JSON tidak ditemukan');
  }

  const jsonString = cleaned.substring(start, end + 1);
  const d = JSON.parse(jsonString);

  const arr = (v) => Array.isArray(v)
    ? v
    : (v ? [String(v)] : []);

  const score = (v) => {
    const n = Number(v);
    return Number.isFinite(n)
      ? Math.max(0, Math.min(10, n))
      : 0;
  };

  return {
    json: {
      candidate_name: d.candidate_name || 'Tidak tercantum',
      it_keywords: arr(d.it_keywords),
      teaching_keywords: arr(d.teaching_keywords),
      it_score: score(d.it_score),
      teaching_score: score(d.teaching_score),
      summary: d.summary || 'Tidak ada ringkasan',
      evidence: arr(d.evidence)
    }
  };
});

return $input.all().map(item => {
  const d = item.json;

  // Mengamankan data array
  const lines = (arr) =>
    Array.isArray(arr) && arr.length
      ? arr.map(x => '• ' + x).join('\n')
      : '• Tidak ditemukan';

  // Membuat pesan Telegram
  const telegram_text = [
    '📋 HASIL SCORING KANDIDAT',
    '',
    '👤 Nama: ' + (d.candidate_name || 'Tidak tercantum'),
    '',
    '💻 Keyword IT:',
    lines(d.it_keywords),
    '',
    '🎓 Keyword Mengajar:',
    lines(d.teaching_keywords),
    '',
    '⭐ Skor Teknis IT: ' + (d.it_score ?? 0) + '/10',
    '⭐ Skor Mengajar: ' + (d.teaching_score ?? 0) + '/10',
    '',
    '📝 Ringkasan:',
    d.summary || 'Tidak ada ringkasan',
    '',
    '🔎 Bukti:',
    lines(d.evidence)
  ].join('\n');

  return {
    json: {
      telegram_text: telegram_text
    }
  };
});
